  return (
    <div
      className="tooltip"
      onMouseLeave={() => closeTooltip()}
      style={{
        position: 'absolute',
        top: tooltip.top,
        left: tooltip.left,
        backgroundColor: 'white',
        padding: '10px',
        border: '1px solid black',
      }}
